Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      if Z.eqb pc RETPC then
        (Nat.leb 5 i && Nat.leb i 6 && CBA.exit_base_chk GT.NF RETPC c ps && CBA.regions_eqb (CC.cp_F c) CPFX && Nat.ltb 103 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0)) && has cells (KWord (SA PE 211) 1 (ELit 1)))%bool
